(140, 336, 'GUG 716988667026', 'DANIELA ', 'FRIMPONG ', NULL, '2004-03-15', 'Female', 'Ghanaian', '0257236623', 'firmpongdaniella@gmail.com', '    House/Building No.: A7 * Street: Anohor Road * Area/Town: Agbogba * City: Accra * Region: Greater Accra * GhanaPost GPS: GM-067-6124', 'Greater Accra', 'La Dade Kotopon (Cantonments / La)', 'University of Ghana', 'BSc. Business Administration (Human Resource Management)', '2026', 'Greater Accra', 'La Dade Kotopon (Cantonments / La)', 'Abuakwa Ultra Centre', 'Administration', '2026', '2026-11-02', '2027-10-29', 'passport/336-daniela-frimpong/1791481096236_IMG_2998.jpeg', 'id_card/336-daniela-frimpong/1791481096769_Ghana_card_.pdf', 'appointment/336-daniela-frimpong/1791481096854_DANIELA_APPOINTMENT_SCHEDULE_37__OPPOSITE_EL-WAK_S_261008_172547.pdf', 'cv/336-daniela-frimpong/1791481096971_My_Resume.pdf', '{\"appointmentLetterData\":{\"appointmentType\":\"TEMPORARY\",\"letterDate\":\"OCTOBER 9, 2026\",\"salutation\":\"Dear Sir/Madam,\",\"customRefNumber\":\"DVLA/HR/NSS/GUG 716988667026\",\"yourRef\":\"\",\"applicantName\":\"DANIELA  FRIMPONG\",\"applicantAddress\":\"    House/Building No.: A7 * Street: Anohor Road * Area/Town: Agbogba * City: Accra * Region: Greater Accra * GhanaPost GPS: GM-067-6124\",\"customSubject\":\"POSTING OF NATIONAL SERVICE PERSONNEL.\",\"customBodyText\":\"This is to inform you that you have been assigned to the <strong>Plaspack, Trade Fair</strong> for the <strong>2026/2027</strong> service year.\\n\\nYour National Service commences on <strong>Monday, October 5, 2026</strong> and ends on <strong>Friday, 29th October, 2027</strong>.\\n\\nYou are required to report to the Head of Department for orientation and assignment. You are expected to exhibit good conduct and abide by all rules and regulations of the Authority throughout your service period.\",\"salaryGrade\":\"DVLA Grade 7 Step 1\",\"probationPeriod\":\"six (6) months\",\"contractDuration\":\"two (2) years\",\"signatoryName\":\"EPHRAIM NII TA